/** English Up 12: original bilingual skill materials. IDs are append-only for profile compatibility. */
import type {CEFR,ReadingUnit,ListeningUnit,WritingTask,ComprehensionQuestion} from './skills-content.ts';
type Fact=[string,string,string,string,string];
type Story=[CEFR,string,string,string,string,[string,string][],Fact[]];
type Dialogue=[CEFR,string,string,string[],string,[string,string][],Fact[]];
function quiz(facts:Fact[]):ComprehensionQuestion[]{return facts.map(([prompt,answer,wrong1,wrong2,explanation],index)=>{const choices=[answer,wrong1,wrong2];const shift=(index+1)%3;const rotated=[...choices.slice(shift),...choices.slice(0,shift)] as [string,string,string];return {prompt,choices:rotated,correct:((3-shift)%3) as 0|1|2,explanation};});}
const stories:Story[]=[
 ['A1','A Library Card','Город','On Monday, Rosa visits the library near her home. She wants a book about animals. The librarian asks for her name and address. Rosa gets a free library card. She can borrow three books for two weeks. She chooses a book about birds and takes it home.','В понедельник Роза приходит в библиотеку рядом с домом. Она хочет книгу о животных. Библиотекарь спрашивает её имя и адрес. Роза получает бесплатный читательский билет. Она может взять три книги на две недели. Роза выбирает книгу о птицах и уносит её домой.',[['library card','читательский билет'],['borrow','брать на время'],['birds','птицы']], [['What does Rosa want to read about?','Animals','Cars','History','Она ищет книгу о животных.'],['How many books can she borrow?','Three','One','Five','По билету можно взять три книги.'],['How long may she keep the books?','Two weeks','One day','A month','Срок выдачи — две недели.']]],
 ['A1','The Missing Key','Дом','Tom comes home at six. He cannot find his key. He checks his backpack, his coat, and his desk. Then his roommate calls him. The key is on the kitchen table. Tom smiles and says thank you. Next time, he wants to put his key in the same place every day.','Том приходит домой в шесть. Он не может найти ключ. Он проверяет рюкзак, пальто и стол. Затем звонит сосед по квартире. Ключ лежит на кухонном столе. Том улыбается и благодарит соседа. В следующий раз он хочет класть ключ в одно место каждый день.',[['roommate','сосед по квартире'],['key','ключ'],['same place','одно место']], [['When does Tom get home?','At six','At four','At eight','Том приходит в шесть.'],['Where is the key?','On the kitchen table','In his coat','At work','Ключ лежит на столе на кухне.'],['Who calls Tom?','His roommate','His teacher','His sister','Ему звонит сосед по квартире.']]],
 ['A1','Cooking for Two','Еда','Lily and Sam make dinner together. Lily washes the tomatoes while Sam cuts the bread. They cook pasta and make a small salad. There is no cheese, so they do not put cheese on the pasta. After dinner, Sam washes the plates. Lily makes tea. They enjoy a quiet evening at home.','Лили и Сэм вместе готовят ужин. Лили моет помидоры, пока Сэм режет хлеб. Они готовят пасту и небольшой салат. Сыра нет, поэтому они не кладут его в пасту. После ужина Сэм моет тарелки, а Лили заваривает чай. Они проводят тихий вечер дома.',[['wash','мыть'],['plates','тарелки'],['salad','салат']], [['What do they cook?','Pasta','Soup','Rice','Они готовят пасту.'],['What is missing?','Cheese','Bread','Tomatoes','В тексте прямо сказано, что в доме не оказалось сыра.'],['Who washes the plates?','Sam','Lily','Both friends','Тарелки моет Сэм.']]],
 ['A1','A Walk in the Park','Свободное время','Every Sunday, Ben walks in the park with his dog Max. They leave home at ten. Max likes to run near the trees, but he stays on a leash. Ben brings water and a small bowl for Max. After the walk, they sit on a bench. Ben reads a book, and Max rests beside him.','Каждое воскресенье Бен гуляет в парке со своей собакой Максом. Они выходят в десять. Макс любит бегать рядом с деревьями, но остаётся на поводке. Бен берёт воду и миску. После прогулки они сидят на скамейке. Бен читает книгу, а Макс отдыхает рядом.',[['leash','поводок'],['bench','скамейка'],['bowl','миска']], [['When do they leave home?','At ten','At nine','At noon','Они выходят в десять.'],['What does Ben bring?','Water and a bowl','A ball and a bike','A newspaper','Он берёт воду и миску.'],['What does Ben do after the walk?','Reads a book','Goes to work','Plays soccer','Он читает книгу на скамейке.']]],
 ['A1','My English Class','Учёба','Nora has English class on Tuesday and Thursday. Her teacher is Mr. Green. There are twelve students in the room. They learn new words, read short texts, and ask questions. Nora is shy, but she speaks English with a partner every lesson. She writes five new words in her notebook after class.','У Норы английский по вторникам и четвергам. Её учитель — мистер Грин. В классе двенадцать учеников. Они учат слова, читают короткие тексты и задают вопросы. Нора стесняется, но на каждом уроке разговаривает на английском с партнёром. После занятия она записывает пять новых слов.',[['shy','стеснительный'],['partner','партнёр'],['notebook','тетрадь']], [['How many students are in the room?','Twelve','Twenty','Eight','В классе двенадцать учеников.'],['When does Nora study?','Tuesday and Thursday','Monday and Friday','Every Saturday','Уроки по вторникам и четвергам.'],['What does Nora write after class?','Five new words','Her phone number','A long story','Она записывает пять слов.']]],
 ['A1','The Farmers Market','Покупки','It is a warm morning in June. Peter visits a farmers market with his mother. They buy apples, carrots, and fresh bread. The apples cost four dollars, and the carrots cost two. Peter carries the bag home. He likes this market because the food is fresh and the sellers are friendly.','Тёплое июньское утро. Питер идёт с мамой на фермерский рынок. Они покупают яблоки, морковь и свежий хлеб. Яблоки стоят четыре доллара, морковь — два. Питер несёт сумку домой. Ему нравится рынок за свежие продукты и дружелюбных продавцов.',[['farmers market','фермерский рынок'],['fresh','свежий'],['sellers','продавцы']], [['How much do the apples cost?','Four dollars','Two dollars','Six dollars','Яблоки стоят четыре доллара.'],['Who goes with Peter?','His mother','His brother','His friend','С ним идёт мама.'],['Why does he like the market?','Fresh food and friendly sellers','Music and games','Cheap clothes','Ему нравятся свежие продукты и продавцы.']]],
 ['A1','Rainy Afternoon','Погода','The weather is rainy today. Mia wants to ride her bike, but she stays inside. She puts on a warm sweater and calls her cousin. They play a word game online for thirty minutes. Later, the rain stops. Mia opens the window and sees a rainbow. She takes a picture and sends it to her cousin.','Сегодня дождливо. Миа хочет покататься на велосипеде, но остаётся дома. Она надевает тёплый свитер и звонит двоюродной сестре. Они полчаса играют онлайн в слова. Позже дождь заканчивается. Миа открывает окно, видит радугу, фотографирует её и отправляет снимок сестре.',[['rainbow','радуга'],['sweater','свитер'],['rain','дождь']], [['Why does Mia stay inside?','It is raining','She has a test','Her bike is broken','Она остаётся дома из-за дождя.'],['How long do they play?','Thirty minutes','Two hours','Ten minutes','Игра длится тридцать минут.'],['What does Mia see later?','A rainbow','A bird','A bus','После дождя появляется радуга.']]],
 ['A1','Visiting Grandma','Семья','On Friday evening, Adam visits his grandmother. She lives in a house with a small garden. Adam brings flowers and helps her make soup. They eat dinner at seven and talk about their week. Before he leaves, Adam waters the plants. His grandmother gives him a bag of cookies for the trip home.','В пятницу вечером Адам навещает бабушку. Она живёт в доме с небольшим садом. Адам приносит цветы и помогает приготовить суп. В семь они ужинают и разговаривают о прошедшей неделе. Перед уходом Адам поливает растения. Бабушка даёт ему печенье на дорогу.',[['garden','сад'],['water the plants','поливать растения'],['cookies','печенье']], [['What does Adam bring?','Flowers','A cake','A book','Он приносит цветы.'],['When do they eat dinner?','At seven','At five','At nine','Они ужинают в семь.'],['What does Adam do before leaving?','Waters the plants','Washes the car','Cleans the windows','Он поливает растения.']]],
 ['A2','The Changed Train','Путешествия','Ava planned to take the 8:15 train to Philadelphia, but a message said the service was canceled. She checked the travel app and found another train at 9:05. It was slower, so she sent her colleague a message explaining that she would arrive after lunch. Her colleague replied that they could move the meeting to two o’clock.','Ава собиралась сесть на поезд в 8:15 до Филадельфии, но получила сообщение об отмене рейса. Она проверила приложение и нашла другой поезд в 9:05. Он был медленнее, поэтому она предупредила коллегу, что прибудет после обеда. Коллега предложил перенести встречу на два часа.',[['canceled','отменённый'],['arrive','прибывать'],['move a meeting','переносить встречу']], [['What happened to the first train?','It was canceled','It was early','It was full','Первый поезд отменили.'],['When was the second train?','At 9:05','At 8:15','At 10:30','Второй поезд отправлялся в 9:05.'],['What time was the meeting moved to?','Two o’clock','Noon','Four o’clock','Встречу перенесли на два часа.']]],
 ['A2','A Fair Return','Покупки','Owen bought headphones online last week. When the package arrived, the left speaker did not work. He read the store’s return policy and learned that defective items could be returned within thirty days. Owen contacted support, sent the order number, and described the problem. The agent offered a replacement instead of a refund, and Owen agreed because he liked the design.','На прошлой неделе Оуэн купил наушники онлайн. Когда посылка пришла, левый динамик не работал. По правилам магазина бракованные товары можно вернуть в течение тридцати дней. Оуэн написал в поддержку, указал номер заказа и описал проблему. Сотрудник предложил замену вместо возврата денег, и Оуэн согласился, потому что ему нравился дизайн.',[['defective','бракованный'],['replacement','замена'],['refund','возврат денег']], [['What was broken?','The left speaker','The charging cable','The microphone','Не работал левый динамик.'],['How long is the return window?','Thirty days','Seven days','Ninety days','Для брака указан срок тридцать дней.'],['What solution did Owen choose?','A replacement','Store credit','A refund','Он выбрал замену.']]],
 ['A2','Part-Time at the Bookshop','Работа','Sophie started a part-time job at a bookshop this month. She works three afternoons a week and sometimes helps on Saturdays. At first, she was nervous about talking to customers, but a colleague showed her how to find books in the catalog. Sophie now enjoys recommending stories to young readers. She is saving her earnings for a short summer trip.','В этом месяце Софи начала подрабатывать в книжном магазине. Она работает три дня в неделю после обеда и иногда по субботам. Сначала ей было тревожно общаться с покупателями, но коллега показал, как искать книги в каталоге. Теперь Софи любит советовать книги молодым читателям и копит деньги на летнюю поездку.',[['part-time','неполный рабочий день'],['catalog','каталог'],['earnings','заработок']], [['Where does Sophie work?','At a bookshop','At a café','At a hospital','Она работает в книжном магазине.'],['Who helped her learn the catalog?','A colleague','A customer','Her brother','Её научил коллега.'],['What is she saving for?','A summer trip','A new laptop','A bicycle','Она копит на летнюю поездку.']]],
 ['A2','The Fitness Reminder','Здоровье','Leo downloaded a fitness app because he wanted to walk more often. The app suggested a daily goal of six thousand steps. During his first week, he reached the goal on four days. On rainy days, he walked inside a shopping center. His friend reminded him that consistent exercise matters more than one perfect day. Leo decided to keep a realistic goal.','Лео скачал фитнес-приложение, потому что хотел чаще ходить пешком. Оно предложило цель — шесть тысяч шагов в день. За первую неделю он достиг цели четыре раза. В дождливые дни он гулял по торговому центру. Друг напомнил, что регулярность важнее одного идеального дня, и Лео решил придерживаться реалистичной цели.',[['steps','шаги'],['consistent','регулярный'],['realistic','реалистичный']], [['What is Leo’s daily goal?','Six thousand steps','Ten thousand steps','Two thousand steps','Цель — шесть тысяч шагов.'],['How many days did he reach it?','Four','Two','Seven','За неделю цель достигнута четыре раза.'],['Where did he walk on rainy days?','A shopping center','A stadium','His office','В дождь он гулял в торговом центре.']]],
 ['A2','Sharing an Apartment','Жильё','Nina and Grace are going to share an apartment next semester. They discussed the rent and agreed to split it equally. Grace likes cooking, so she offered to buy kitchen supplies. Nina suggested creating a cleaning schedule because both of them will be busy with classes. They also decided to ask before inviting guests to stay overnight.','Нина и Грейс будут снимать квартиру вместе в следующем семестре. Они договорились делить аренду поровну. Грейс любит готовить и предложила купить кухонные принадлежности. Нина предложила составить график уборки, потому что обе будут заняты учёбой. Они также решили предупреждать друг друга о гостях, остающихся на ночь.',[['split equally','делить поровну'],['supplies','принадлежности'],['overnight','на ночь']], [['How will they share the rent?','Equally','By room size','One person pays everything','Они делят плату поровну.'],['Who will buy kitchen supplies?','Grace','Nina','The landlord','Принадлежности купит Грейс.'],['Why make a cleaning schedule?','Both are busy','The apartment is very large','They have a dog','У обеих много занятий.']]],
 ['A2','A Neighborhood Festival','События','Last Saturday, the neighborhood held a small street festival. Residents sold homemade snacks and played music in the park. Visitors could donate money to the local animal shelter. Maya volunteered at the information table and helped people find the activity areas. By the end of the day, the organizers had collected enough donations to buy food and blankets for the shelter.','В прошлую субботу жители района организовали небольшой уличный фестиваль. Они продавали домашние закуски и играли музыку в парке. Посетители могли пожертвовать деньги местному приюту для животных. Майя помогала на стойке информации. К концу дня удалось собрать достаточно денег на корм и одеяла для приюта.',[['residents','жители'],['donations','пожертвования'],['shelter','приют']], [['What was the fundraising goal?','Help an animal shelter','Build a parking lot','Buy new streetlights','Собирали средства приюту.'],['What did Maya do?','Helped at information table','Cooked all the food','Played the guitar','Майя работала на стойке информации.'],['Where was music played?','In the park','At the library','At the airport','Музыка звучала в парке.']]],
 ['A2','Booking a Checkup','Здоровье','Chris wanted to schedule a routine medical checkup. He used an online booking form and chose Thursday morning. The clinic sent him a confirmation email with the address and instructions. It asked him to bring an ID and a list of medications. On Wednesday, Chris realized he had a work meeting and called to reschedule the appointment for Friday.','Крис хотел записаться на профилактический осмотр. Он выбрал утро четверга через онлайн-форму. Клиника прислала подтверждение с адресом и инструкциями: взять удостоверение личности и список лекарств. В среду он вспомнил о рабочей встрече и позвонил, чтобы перенести приём на пятницу.',[['checkup','осмотр'],['confirmation','подтверждение'],['reschedule','перенести']], [['When was the first appointment?','Thursday morning','Monday evening','Friday afternoon','Первоначально он записался на четверг утром.'],['What should he bring?','ID and medication list','A photograph','A work contract','Клиника попросила документ и список лекарств.'],['When was it moved to?','Friday','Saturday','Tuesday','Приём перенесли на пятницу.']]],
 ['A2','A Transfer Update','Payment Support','A customer asked why a bank transfer was still pending. The support agent checked the transaction reference but could not confirm a completion time. She explained that some transfers require additional processing by the bank. She offered to send an update after the next verified status change. The customer appreciated the clear explanation and did not need to share any password.','Клиент спросил, почему банковский перевод всё ещё обрабатывается. Специалист проверила идентификатор транзакции, но не смогла подтвердить время завершения. Она объяснила, что некоторые переводы требуют дополнительной обработки банком, и пообещала сообщить после подтверждённого изменения статуса. Клиент оценил ясность ответа и не сообщал пароль.',[['pending','в обработке'],['reference','идентификатор'],['verified','подтверждённый']], [['What status did the transfer have?','Pending','Refunded','Rejected','Перевод был в обработке.'],['What could the agent not confirm?','Completion time','Transaction reference','Customer name','Точное время завершения неизвестно.'],['What was not requested?','Password','Transaction reference','Status update','Пароль не запрашивался.']]],
 ['B1','A Useful Handover','Customer Support','Before finishing her shift, Priya reviewed three unresolved support tickets. The first involved a delayed transfer, the second concerned a failed login, and the third needed a response from a merchant. She wrote a concise handover for the next agent, including the steps already taken and the next action required. Because she separated confirmed facts from guesses, the next shift could continue without repeating the same checks.','Перед концом смены Прия проверила три незакрытых обращения: задержку перевода, проблему со входом и запрос ответа от мерчанта. Она передала следующему сотруднику краткую сводку о выполненных действиях и следующих шагах. Поскольку подтверждённые факты были отделены от предположений, следующая смена смогла продолжить работу без повторных проверок.',[['handover','передача смены'],['unresolved','нерешённый'],['confirmed facts','подтверждённые факты']], [['How many tickets were unresolved?','Three','Two','Five','Незакрытых обращений было три.'],['What did the third case need?','A merchant response','A new password','A refund receipt','Третий случай ожидал ответа мерчанта.'],['Why did the handover help?','It separated facts from guesses','It promised fast refunds','It closed all cases','Это помогло избежать повторных проверок.']]],
 ['B1','The Moving Budget','Финансы','Before moving to Denver, Oliver calculated the cost of the move. His budget included a deposit, the first month’s rent, transportation, and essential furniture. He compared two apartments: one had lower rent but a longer commute, while the other cost more but was near work. After calculating monthly travel expenses, Oliver chose the second option because its overall cost was lower than he had expected.','Перед переездом в Денвер Оливер рассчитал расходы: залог, первый месяц аренды, транспорт и необходимую мебель. Он сравнил две квартиры: одна дешевле, но дальше от работы; другая дороже, зато ближе. Посчитав транспортные расходы за месяц, Оливер выбрал второй вариант, поскольку общая стоимость оказалась ниже ожидаемой.',[['deposit','залог'],['commute','дорога на работу'],['overall cost','общая стоимость']], [['Which apartment did Oliver choose?','The one near work','The cheaper one farther away','Neither','Он выбрал квартиру рядом с работой.'],['What did he compare besides rent?','Travel expenses','Gym memberships','Food prices','Он учёл транспортные расходы.'],['What city was he moving to?','Denver','Austin','Boston','Он переезжал в Денвер.']]],
 ['B1','A Better Bus Route','Город','The city proposed changing a bus route because many residents had complained about overcrowding. The transport department suggested adding two morning services, but it planned to remove a quiet evening stop. At a public meeting, several workers explained that they depended on that stop after late shifts. The department agreed to review passenger data before making a final decision.','Город предложил изменить автобусный маршрут из-за жалоб на переполненность. Транспортное ведомство хотело добавить два утренних рейса, но убрать остановку в вечернее время. На встрече жители, работающие допоздна, объяснили, что эта остановка им необходима. Ведомство согласилось изучить данные о пассажирах перед окончательным решением.',[['overcrowding','переполненность'],['public meeting','общественная встреча'],['passenger data','данные пассажиропотока']], [['Why was the route reviewed?','Overcrowding complaints','Road construction','A new airport','Поводом стали жалобы на переполненность.'],['What would be added?','Two morning services','Three night buses','A metro station','Планировались два дополнительных утренних рейса.'],['What did evening workers request?','Keep the late stop','Lower ticket prices','More parking','Работникам нужна вечерняя остановка.']]],
 ['B1','Learning from a Mentor','Карьера','When Mateo joined a software support team, he was comfortable with computers but unfamiliar with their ticket system. His mentor asked him to observe experienced agents before answering complex cases alone. During the first month, Mateo practiced writing clear summaries and asking useful follow-up questions. He became more confident after he learned that good support was not about having every answer immediately; it was about investigating carefully.','Когда Матео пришёл в техническую поддержку, он уверенно пользовался компьютером, но не знал систему тикетов. Наставник посоветовал сначала наблюдать за опытными сотрудниками. В первый месяц Матео учился писать понятные сводки и задавать уточняющие вопросы. Он понял, что хорошая поддержка — не мгновенные ответы на всё, а тщательная проверка.',[['mentor','наставник'],['follow-up question','уточняющий вопрос'],['investigate','исследовать']], [['What was new to Mateo?','The ticket system','Using computers','Speaking English','Он не знал систему обращений.'],['What did he practice?','Writing summaries and questions','Building a website','Sales calls','Он учился писать сводки и вопросы.'],['What did he learn about support?','Careful investigation matters','Quick guesses are best','Every case is simple','Важнее проверять, чем угадывать.']]],
 ['B1','A Payment Dispute','FinTech','A customer disputed a card payment that appeared twice in the transaction history. The first entry had been settled, while the second was still an authorization hold. The agent explained the difference and suggested waiting for the bank to release the hold according to its policy. She recorded the case for follow-up rather than incorrectly claiming that the customer had been charged twice.','Клиент оспаривал карточный платёж, который дважды отображался в истории. Первая запись была окончательным списанием, а вторая — временной блокировкой при авторизации. Сотрудница объяснила разницу и рекомендовала дождаться снятия блокировки банком по его правилам. Она оставила обращение на контроле, вместо того чтобы ошибочно заявить о двойном списании.',[['settled','проведённый'],['authorization hold','блокировка при авторизации'],['dispute','спор']], [['What was the second entry?','An authorization hold','A completed refund','A chargeback','Вторая запись была временной блокировкой.'],['What did the agent avoid saying?','The customer was charged twice','The case needs follow-up','The bank sets the policy','Она не утверждала двойное списание без оснований.'],['What happened to the first entry?','It had settled','It was canceled','It was declined','Первая операция была проведена.']]],
 ['B1','A Privacy Reminder','Работа','At a team meeting, Lena noticed that support agents sometimes pasted customer details into shared chat channels. She suggested a simple rule: use case references in open discussions and keep sensitive information inside the approved system. The manager agreed and organized a short refresher training. Within a month, staff were using safer messages, and fewer conversations needed correction.','На встрече команды Лена заметила, что сотрудники поддержки иногда пересылают данные клиентов в общие чаты. Она предложила обсуждать дела по идентификаторам, а чувствительную информацию оставлять только в утверждённой системе. Руководитель согласился и провёл краткое обучение. Через месяц сотрудники стали писать безопаснее.',[['sensitive information','чувствительная информация'],['approved system','разрешённая система'],['refresher training','повторное обучение']], [['What was Lena concerned about?','Customer details in shared chats','Slow coffee machines','Office furniture','Она беспокоилась о данных клиентов в чатах.'],['What did she propose using?','Case references','Full card numbers','Passwords','В общих обсуждениях — только ссылки на обращения.'],['What did the manager arrange?','Refresher training','A new office','Extra vacation','Руководитель организовал обучение.']]],
 ['B1','Community Garden','Общество','A group of neighbors turned an empty lot into a community garden. They applied for permission, collected tools, and divided the work between volunteers. Some people planted vegetables, while others built paths and collected rainwater. At the end of summer, the garden produced enough food for a small neighborhood meal. More importantly, residents who had rarely spoken before began helping each other.','Соседи превратили пустой участок в общественный сад. Они получили разрешение, собрали инструменты и распределили задачи. Одни высаживали овощи, другие делали дорожки и собирали дождевую воду. К концу лета урожая хватило на небольшой общий ужин. Главное — люди, почти не общавшиеся раньше, начали помогать друг другу.',[['empty lot','пустой участок'],['volunteers','волонтёры'],['rainwater','дождевая вода']], [['What was the site before the project?','An empty lot','A parking garage','A store','Раньше это был пустой участок.'],['What did volunteers collect?','Rainwater','Tickets','Books','Они собирали дождевую воду.'],['What was the social benefit?','Neighbors got to know each other','Everyone moved away','A company bought the garden','Соседи стали больше общаться.']]],
 ['B1','Planning a Workshop','Учёба','A community center planned a workshop about digital safety. The organizer originally expected twenty participants, but forty people registered within two days. Instead of canceling, she reserved a larger room and asked a colleague to prepare a second demonstration. The workshop covered strong passwords, suspicious links, and ways to report scams. Attendees were given a printed checklist to use at home.','Общественный центр планировал семинар по цифровой безопасности для двадцати человек, но за два дня записались сорок. Организатор забронировала зал побольше и попросила коллегу подготовить вторую демонстрацию. На семинаре обсуждали надёжные пароли, подозрительные ссылки и способы сообщать о мошенничестве. Участники получили памятку.',[['workshop','семинар'],['scam','мошенничество'],['checklist','памятка']], [['How many people registered?','Forty','Twenty','Sixty','Зарегистрировались сорок человек.'],['What did the organizer change?','Booked a larger room','Canceled the event','Moved it online','Она забронировала зал побольше.'],['What did attendees take home?','A printed checklist','A tablet','A gift card','Участники получили памятку.']]],
 ['B2','The Root Cause Review','IT / FinTech','Following a brief payment outage, the incident team compared server logs with deployment records. Although the disruption began soon after a software release, the engineers resisted treating timing alone as proof of causation. They discovered that an outdated configuration had limited the connection pool under heavy traffic. The report distinguished verified evidence from hypotheses and recommended both a rollback drill and realistic load testing.','После короткого сбоя платежей команда сопоставила журналы сервера с данными о релизах. Хотя сбой начался вскоре после обновления, инженеры не сочли одно лишь совпадение по времени доказательством причины. Они обнаружили устаревшую конфигурацию, ограничивающую пул подключений при высокой нагрузке. В отчёте факты были отделены от гипотез, а в рекомендациях появились учения по откату и нагрузочное тестирование.',[['outage','сбой'],['causation','причинно-следственная связь'],['rollback','откат']], [['What actually limited capacity?','An outdated configuration','A missing invoice','An email filter','Ограничение вызвала старая конфигурация.'],['What did engineers avoid assuming?','Timing proves causation','A rollback is possible','Traffic can increase','Время совпадения не доказывает причину.'],['Which prevention was recommended?','Load testing','Ignoring logs','Disabling monitoring','Рекомендовано нагрузочное тестирование.']]],
 ['B2','When Data Is Too Personal','Технологии','A marketing team wanted to personalize recommendations using detailed customer behavior. The product manager argued that the additional data could improve accuracy, while the privacy officer questioned whether every field was necessary. They agreed to test a smaller, anonymized dataset before requesting wider access. The decision delayed the launch slightly but established a clearer purpose for collection and reduced the amount of sensitive information involved.','Маркетологи хотели персонализировать рекомендации на основе подробного поведения клиентов. Менеджер продукта считал, что больше данных повысит точность, а специалист по приватности сомневался в необходимости каждого поля. Они решили проверить меньший анонимизированный набор, прежде чем запрашивать широкий доступ. Запуск слегка задержался, но цель сбора стала яснее, а объём чувствительных данных уменьшился.',[['anonymized','обезличенный'],['privacy officer','специалист по приватности'],['dataset','набор данных']], [['What was the compromise?','Test a smaller anonymized dataset','Collect every available field','Cancel recommendations forever','Они решили проверить меньший обезличенный набор.'],['What was one cost of the decision?','A slight launch delay','Lost office space','Higher rent','Запуск немного задержался.'],['Who questioned the necessity of the fields?','The privacy officer','A driver','A sales customer','Сомнения высказал специалист по приватности.']]],
 ['B2','International Transfer Fees','FinTech','When comparing two cross-border payment providers, Anika realized that the advertised transfer fee told only part of the story. One provider charged a flat amount but offered a weaker exchange rate; the other charged a higher visible fee but converted money more favorably. Rather than comparing percentages in isolation, she calculated the amount the recipient would actually receive. Her report also noted that delivery estimates were not guarantees.','Сравнивая двух провайдеров международных переводов, Аника поняла, что объявленная комиссия показывает лишь часть картины. Первый взимал фиксированную сумму, но использовал менее выгодный курс, второй — более высокую видимую комиссию, зато лучший курс обмена. Она сравнила фактическую сумму получения и отдельно отметила, что сроки доставки — оценки, а не гарантии.',[['exchange rate','обменный курс'],['recipient','получатель'],['flat fee','фиксированная комиссия']], [['What did Anika compare in the end?','Amount received','Website design','Office hours','Она сравнила итоговую сумму у получателя.'],['Why was a low fee potentially misleading?','Exchange rates differed','Transfer IDs were missing','All fees were free','Низкую комиссию мог нивелировать курс.'],['How were delivery times described?','Estimates, not guarantees','Fixed legal promises','Never available','Сроки были приблизительными.']]],
 ['B2','A Hybrid Work Trial','Карьера','A mid-sized company introduced a three-month hybrid work trial. Employees could work remotely for part of the week, provided that their teams agreed on shared availability hours. Surveys showed that individual focus improved, but spontaneous collaboration became less frequent. Rather than declaring the policy a success or failure, management compared task outcomes, employee feedback, and meeting quality before proposing adjustments.','Компания среднего размера ввела трёхмесячный эксперимент с гибридным форматом. Сотрудники могли часть недели работать удалённо, согласовав общие часы доступности. Опросы показали улучшение концентрации, но меньше спонтанного взаимодействия. Вместо поспешной оценки руководство сопоставило результаты задач, отзывы сотрудников и качество встреч, прежде чем менять правила.',[['hybrid work','гибридная работа'],['shared availability','общие часы доступности'],['outcomes','результаты']], [['How long was the trial?','Three months','One week','One year','Эксперимент длился три месяца.'],['What became less frequent?','Spontaneous collaboration','Individual focus','Online meetings','Спонтанного общения стало меньше.'],['How did management judge it?','Using several kinds of evidence','Only office attendance','A single complaint','Они учитывали результаты и отзывы.']]],
 ['B2','An Unusual Payment Pattern','Fraud Prevention','An antifraud analyst noticed a sudden cluster of small transactions originating from newly created accounts. The pattern was suspicious, but not sufficient to conclude that every transaction was fraudulent. She recommended temporary risk-based checks and a review of device and timing signals, while avoiding unnecessary restrictions on legitimate customers. The team documented its reasoning so that later reviewers could understand both the decision and its limitations.','Аналитик антифрода заметила всплеск небольших операций от недавно созданных аккаунтов. Поведение выглядело подозрительным, но этого недостаточно, чтобы назвать все транзакции мошенническими. Она предложила временные проверки по уровню риска и анализ устройств и времени, стараясь не ограничивать добросовестных клиентов. Команда задокументировала основания решения и его ограничения.',[['cluster','скопление'],['fraudulent','мошеннический'],['legitimate','добросовестный']], [['Why was the pattern investigated?','Many small transfers from new accounts','A single late login','An old invoice','Подозрение вызвал кластер операций новых аккаунтов.'],['What did the analyst avoid assuming?','All transactions were fraud','Extra review was possible','Timing signals mattered','Она не назвала все операции мошенническими.'],['What was recorded?','Reasoning and limitations','Customer passwords','Marketing slogans','Команда зафиксировала логику и ограничения решения.']]],
 ['B2','A Difficult Lease Discussion','Жильё','After moving into a rented apartment, Morgan discovered a persistent leak near the window. The landlord initially suggested that condensation was responsible, whereas Morgan provided dated photos showing water entering during heavy rain. Both parties reviewed the lease and agreed to arrange an independent inspection. Their written exchange remained factual, which reduced tension and helped them decide on a repair schedule without assigning blame prematurely.','После переезда в арендованную квартиру Морган обнаружил протечку у окна. Арендодатель считал причиной конденсат, но Морган показал датированные фотографии воды во время сильного дождя. Они изучили договор и договорились о независимой проверке. Переписка оставалась фактической, что снизило напряжение и помогло согласовать ремонт без преждевременных обвинений.',[['persistent leak','постоянная протечка'],['condensation','конденсат'],['inspection','осмотр']], [['What evidence did Morgan provide?','Dated photos','A neighbor’s guess','A receipt for food','Морган предъявил фотографии с датами.'],['What did both sides agree to?','An independent inspection','Immediate eviction','Ignore the damage','Они договорились о независимом осмотре.'],['What reduced tension?','Factual written communication','Public accusations','Ignoring the lease','Фактический тон помог избежать конфликта.']]],
 ['B2','Interviewing with AI Tools','Карьера','A recruiting department considered using an automated system to rank interview applications. Its supporters expected faster screening, but several employees raised concerns about explainability and potential bias. Before approving the tool, the department arranged a small evaluation with human review and clear appeal procedures. The team concluded that automation could assist decisions, yet accountability should remain with trained staff.','Отдел подбора персонала обсуждал систему автоматического ранжирования заявок. Сторонники ожидали ускорения, но коллеги опасались непрозрачности и возможной предвзятости. До внедрения они организовали небольшую проверку с участием людей и понятной процедурой апелляции. Команда решила, что автоматизация может помогать, но ответственность должна оставаться за специалистами.',[['explainability','объяснимость'],['bias','предвзятость'],['accountability','ответственность']], [['What was a main concern?','Potential bias','Too many office plants','Long lunch breaks','Обсуждали возможную предвзятость.'],['What accompanied the evaluation?','Human review','Automatic rejection of everyone','No documentation','Проверка проходила с участием людей.'],['Who remains accountable?','Trained staff','The software alone','Job applicants','Ответственность остаётся за сотрудниками.']]],
 ['B2','After the Flood','Общество','When severe rain flooded several streets, local volunteers created a temporary coordination group. They prioritized residents who could not travel independently, checked official safety notices, and avoided forwarding unverified rumors. Businesses donated water and cleaning supplies, while the community center provided a place to exchange information. The recovery took weeks, but the shared planning made assistance more reliable and transparent.','После сильных дождей затопило несколько улиц. Волонтёры организовали временную группу, уделив внимание жителям, которым трудно передвигаться самостоятельно. Они проверяли официальные сообщения и не распространяли слухи. Компании предоставили воду и средства для уборки, а центр сообщества помогал обмениваться информацией. Восстановление заняло недели, но совместное планирование сделало помощь надёжнее.',[['flooded','затопленный'],['unverified','непроверенный'],['recovery','восстановление']], [['Who received priority assistance?','People unable to travel independently','Only local businesses','Visitors at hotels','В первую очередь помогали маломобильным жителям.'],['What information did volunteers avoid?','Unverified rumors','Official notices','Safety updates','Они избегали непроверенных слухов.'],['How long did recovery take?','Weeks','Minutes','One afternoon','Восстановление заняло недели.']]],
];
const dialogues:Dialogue[]=[
 ['A1','At the Coffee Counter','Кафе',['Barista: Good morning! What would you like?','Maya: A small latte, please.','Barista: Hot or iced?','Maya: Hot, please. How much is it?','Barista: Four dollars.','Maya: Here you go. Thank you!'], 'Бариста приветствует Майю. Она заказывает маленький горячий латте за четыре доллара.',[['hot or iced','горячий или со льдом'],['here you go','вот, пожалуйста']], [['What drink does Maya order?','A small latte','A large tea','A cold soda','Майя заказывает маленький латте.'],['Does she want ice?','No','Yes','She does not say','Она просит горячий напиток.'],['How much does it cost?','Four dollars','Three dollars','Five dollars','Бариста называет цену четыре доллара.']]],
 ['A1','Finding the Classroom','Учёба',['Student: Excuse me, where is room twelve?','Teacher: Go upstairs and turn left.','Student: Is it next to the library?','Teacher: Yes, the blue door.','Student: Thank you!','Teacher: You are welcome.'], 'Студент ищет кабинет двенадцать. Преподаватель советует подняться наверх и повернуть налево; синяя дверь рядом с библиотекой.',[['upstairs','наверх'],['turn left','поверните налево']], [['Which room does the student need?','Room twelve','Room twenty','Room two','Нужен кабинет двенадцать.'],['Where should the student turn?','Left','Right','Back','Нужно повернуть налево.'],['What color is the door?','Blue','Red','White','Дверь синяя.']]],
 ['A1','Choosing a Bus Ticket','Транспорт',['Driver: Hello. One ticket?','Leo: Yes, please. Is this bus going downtown?','Driver: Yes, it stops at Main Street.','Leo: Great. How much is the ticket?','Driver: Two dollars.','Leo: Thank you!'], 'Лео покупает билет за два доллара на автобус в центр города, который останавливается на Мейн-стрит.',[['downtown','центр города'],['ticket','билет']], [['Where is Leo going?','Downtown','To the beach','To school','Автобус едет в центр.'],['Where does the bus stop?','Main Street','Oak Park','The airport','Остановка на Мейн-стрит.'],['What is the fare?','Two dollars','Five dollars','One dollar','Билет стоит два доллара.']]],
 ['A1','Weekend Invitation','Друзья',['Anna: Are you free on Saturday?','Noah: Yes, in the afternoon.','Anna: Do you want to play basketball?','Noah: Sure. Where?','Anna: At the park near my house, at three.','Noah: Sounds good!'], 'Анна зовёт Ноа играть в баскетбол в субботу в три часа в парке у её дома.',[['be free','быть свободным'],['sounds good','отлично']], [['What activity do they plan?','Basketball','Swimming','Cycling','Они собираются играть в баскетбол.'],['When will they meet?','Saturday at three','Sunday at two','Friday at five','Встреча в субботу в три.'],['Where will they play?','At the park','At school','At the gym','Они встретятся в парке.']]],
 ['A1','A Simple Grocery List','Покупки',['Eva: Do we have any milk?','Mark: No, but we have eggs.','Eva: Let us buy milk and apples.','Mark: Do we need bread?','Eva: Yes, one loaf, please.','Mark: I will write it down.'], 'Ева и Марк составляют список продуктов: молоко, яблоки и одна буханка хлеба. Яйца уже есть.',[['loaf','буханка'],['write it down','записать']], [['What do they already have?','Eggs','Milk','Apples','Яйца уже есть.'],['How much bread do they need?','One loaf','Two loaves','No bread','Нужна одна буханка.'],['Who writes the list?','Mark','Eva','A cashier','Список записывает Марк.']]],
 ['A1','Calling Home','Семья',['Dad: Hi, Lucy! How are you?','Lucy: I am fine. I am at the station.','Dad: When is your train?','Lucy: At seven thirty.','Dad: Call me when you arrive.','Lucy: I will. Bye!'], 'Люси звонит папе со станции. Её поезд в 7:30, и отец просит позвонить после прибытия.',[['station','станция'],['arrive','прибыть']], [['Where is Lucy?','At the station','At school','At home','Люси на станции.'],['When is the train?','At seven thirty','At six','At eight thirty','Поезд в 7:30.'],['What does Dad ask?','Call after arriving','Buy some bread','Change the train','Он просит позвонить по прибытии.']]],
 ['A1','The Weather Forecast','Погода',['Host: Tomorrow morning will be sunny.','Guest: Is it going to rain later?','Host: Yes, around five in the afternoon.','Guest: I have a picnic at noon.','Host: Noon should be dry.','Guest: Great news!'], 'Ведущий прогнозирует солнечное утро и дождь около пяти вечера. Пикник в полдень должен пройти без дождя.',[['forecast','прогноз'],['dry','без осадков']], [['When is rain expected?','Around five','At noon','At eight','Дождь ожидается около пяти.'],['When is the picnic?','At noon','At seven','At ten','Пикник в полдень.'],['What will morning weather be?','Sunny','Snowy','Windy','Утро будет солнечным.']]],
 ['A1','A New Neighbor','Знакомство',['Rita: Hello! I am Rita from apartment four.','Dan: Hi! I am Dan. I just moved in.','Rita: Welcome! Do you need help?','Dan: Thank you. Where is the laundry room?','Rita: It is in the basement.','Dan: Thanks for telling me.'], 'Рита знакомится с новым соседом Дэном. Она объясняет, что прачечная находится в подвале.',[['laundry room','прачечная'],['basement','подвал']], [['Which apartment is Rita in?','Four','Three','Seven','Рита живёт в квартире четыре.'],['Who just moved in?','Dan','Rita','A manager','Недавно переехал Дэн.'],['Where is the laundry room?','In the basement','On the roof','Next to the lobby','Прачечная в подвале.']]],
 ['A2','Rescheduling a Dentist Visit','Здоровье',['Patient: I have an appointment on Tuesday at ten.','Receptionist: How can I help?','Patient: Can I move it to Thursday afternoon?','Receptionist: We have a slot at three thirty.','Patient: That works for me.','Receptionist: I will send confirmation by email.'], 'Пациент переносит запись к стоматологу со вторника на четверг в 15:30. Регистратор отправит подтверждение по почте.',[['appointment','запись'],['slot','свободное время']], [['What day was the original visit?','Tuesday','Monday','Friday','Первоначальный день — вторник.'],['What time is the new slot?','Three thirty','Two thirty','Four','Новое время — 15:30.'],['How will confirmation arrive?','By email','By mail','By phone call','Подтверждение придёт по электронной почте.']]],
 ['A2','Wrong Size Shoes','Покупки',['Customer: I ordered size eight, but these are size nine.','Agent: I am sorry about that. Do you have the order number?','Customer: Yes, it is 5278.','Agent: We can arrange an exchange.','Customer: Is return shipping free?','Agent: Yes, for incorrect items.'], 'Клиент получил обувь девятого размера вместо восьмого. Поддержка предложила обмен и бесплатную обратную доставку ошибочного товара.',[['exchange','обмен'],['return shipping','обратная доставка']], [['Which size was ordered?','Eight','Nine','Seven','Клиент заказывал восьмой размер.'],['What is the order number?','5278','5728','5287','Номер заказа 5278.'],['Is return shipping free?','Yes','No','Only on weekends','Обратная доставка ошибочного товара бесплатна.']]],
 ['A2','Apartment Viewing','Жильё',['Tenant: Is water included in the rent?','Landlord: Yes, but electricity is separate.','Tenant: What about the security deposit?','Landlord: One month of rent.','Tenant: Can I see the apartment on Friday?','Landlord: Sure, at five p.m.'], 'Арендодатель объясняет: вода включена в аренду, электричество отдельно, залог равен месячной плате. Просмотр в пятницу в пять.',[['deposit','залог'],['separate','оплачиваемый отдельно']], [['What is included in rent?','Water','Electricity','Internet','Вода включена.'],['How large is the deposit?','One month of rent','Two weeks of rent','Two months of rent','Залог равен месячной аренде.'],['When is the viewing?','Friday at five','Thursday at six','Saturday at three','Просмотр в пятницу в пять.']]],
 ['A2','Checking a Payment','Payment Support',['Customer: My payment has been pending since yesterday.','Agent: Could you provide the transaction reference?','Customer: I have the reference, but no receipt yet.','Agent: I will check the verified status.','Customer: Can you promise it will arrive today?','Agent: I cannot confirm the timing before the check.'], 'Клиент спрашивает о платеже в обработке. Сотрудник запрашивает идентификатор и не обещает дату завершения до проверки.',[['pending','в обработке'],['receipt','квитанция']], [['What does the agent request?','Transaction reference','Password','Card PIN','Сотрудник просит идентификатор.'],['How long has the payment been pending?','Since yesterday','One hour','A week','Платёж в ожидании со вчерашнего дня.'],['Does the agent promise arrival today?','No','Yes','Only after lunch','Он не обещает срок до проверки.']]],
 ['A2','Meeting a Colleague','Работа',['Jade: Are we still meeting at eleven?','Sam: I have a client call until eleven fifteen.','Jade: Could we start at eleven thirty?','Sam: That would be perfect.','Jade: I will update the calendar invitation.','Sam: Thanks for being flexible.'], 'Коллеги переносят встречу с 11:00 на 11:30, потому что у Сэма клиентский звонок до 11:15.',[['flexible','гибкий'],['invitation','приглашение']], [['What time was the original meeting?','Eleven','Ten','Twelve','Сначала встреча была в одиннадцать.'],['Why is Sam late?','A client call','A train delay','An interview','У него клиентский звонок.'],['What is the new start time?','Eleven thirty','Eleven fifteen','Twelve thirty','Новое время — 11:30.']]],
 ['A2','Choosing a Museum Pass','Путешествия',['Visitor: How much is the day pass?','Clerk: Eighteen dollars. It includes the art museum and the history hall.','Visitor: Can I use it tomorrow?','Clerk: No, only today.','Visitor: Then I will buy two tickets.','Clerk: You can pay by card.'], 'Посетитель покупает два билета на один день по восемнадцать долларов. Билет включает художественный музей и зал истории.',[['day pass','дневной билет'],['includes','включает']], [['How much is one pass?','Eighteen dollars','Eight dollars','Twenty dollars','Один билет стоит 18 долларов.'],['When is it valid?','Today only','Tomorrow','All week','Билет действителен только сегодня.'],['What does it include?','Art and history venues','A bus ride','A restaurant meal','Включены два музейных пространства.']]],
 ['A2','Ordering Delivery','Еда',['Customer: I placed my order forty minutes ago.','Agent: May I have your order number?','Customer: It is 6904.','Agent: The driver is on the way, but traffic is heavy.','Customer: Can you give me an exact time?','Agent: I can share the latest estimate, not a guarantee.'], 'Клиент ждёт доставку сорок минут. Курьер в пути, но движение плотное. Сотрудник может назвать оценку, но не гарантированное время.',[['driver','курьер'],['estimate','предположительная оценка']], [['How long has the customer waited?','Forty minutes','Twenty minutes','One hour','Клиент ждёт сорок минут.'],['What is delaying the driver?','Heavy traffic','Bad weather','A flat tire','На дороге пробки.'],['Can the agent guarantee the time?','No','Yes','For an extra fee','Время — только оценка.']]],
 ['A2','At the Bank Counter','Банк',['Customer: I would like to open a checking account.','Clerk: Certainly. Do you have your identification?','Customer: Yes, and proof of address.','Clerk: Great. We will review your documents first.','Customer: How long will that take?','Clerk: It depends on verification.'], 'Клиент хочет открыть текущий счёт. Он принёс удостоверение и документ с адресом. В банке предупреждают, что срок зависит от проверки.',[['checking account','текущий счёт'],['proof of address','подтверждение адреса']], [['What kind of account is requested?','Checking','Savings','Business loan','Клиент хочет текущий счёт.'],['What documents are mentioned?','ID and proof of address','A passport photo only','A receipt for lunch','Нужны удостоверение и подтверждение адреса.'],['What affects the waiting time?','Verification','Weather','Cashier breaks','Срок зависит от проверки.']]],
 ['B1','A Careful Refund Reply','Customer Support',['Customer: I requested a refund five days ago. Is it approved?','Agent: I can see your request, but final approval is still pending.','Customer: Should I submit it again?','Agent: Please do not duplicate the request.','Customer: What should I expect next?','Agent: We will update you when the decision is confirmed.'], 'Клиент спрашивает о возврате, заявленном пять дней назад. Решение ещё не подтверждено; подавать повторный запрос не нужно.',[['duplicate','дублировать'],['approval','одобрение']], [['How long ago was the request made?','Five days','Two days','One week','Заявка подана пять дней назад.'],['Is approval confirmed?','No','Yes','It was declined','Решение ещё не подтверждено.'],['Should the customer submit it again?','No','Yes','Only by phone','Повторять запрос не требуется.']]],
 ['B1','A Difficult Interview Question','Карьера',['Recruiter: Tell me about a time you made a mistake.','Candidate: I once sent an unclear update to a colleague.','Recruiter: What did you do after you noticed?','Candidate: I corrected the message and explained the missing details.','Recruiter: What did you learn?','Candidate: To check important information before sending it.'], 'Рекрутер просит рассказать об ошибке. Кандидат вспоминает неясное сообщение, которое исправил, и говорит об уроке: проверять важные сведения перед отправкой.',[['unclear','неясный'],['missing details','недостающие детали']], [['What mistake did the candidate make?','Sent an unclear update','Forgot an interview','Lost a customer file','Он отправил неясное сообщение.'],['How did they respond?','Corrected and explained it','Ignored it','Blamed a colleague','Кандидат исправил сообщение.'],['What did they learn?','Check before sending','Write faster','Avoid email entirely','Он научился проверять информацию.']]],
 ['B1','Escalating a Ticket','Работа',['Agent: Ticket 842 is still unresolved after our checks.','Lead: Do we have the transaction reference and error log?','Agent: Yes, both are attached in the secure system.','Lead: Then escalate it to the payment provider.','Agent: Should I tell the customer a resolution time?','Lead: Not until the provider confirms one.'], 'Не решённый тикет 842 эскалируют провайдеру. Ссылка на транзакцию и журнал ошибки хранятся в безопасной системе. Обещать срок до подтверждения нельзя.',[['escalate','передавать на следующий уровень'],['secure system','защищённая система']], [['Which ticket is discussed?','842','824','482','Обсуждают тикет 842.'],['Where are the supporting records?','Secure system','Public chat','Printed flyers','Данные в защищённой системе.'],['When may staff give a resolution time?','After provider confirmation','Immediately','Before any checks','Срок называют только после подтверждения.']]],
 ['B1','A Product Feedback Session','Технологии',['Manager: Users say the new filter is confusing.','Designer: The button label might be unclear.','Manager: How can we check that?','Designer: We could test two versions with volunteers.','Manager: What should we measure?','Designer: Whether users can complete the task without help.'], 'Команда обсуждает сложный фильтр в приложении. Дизайнер предлагает проверить две версии на добровольцах и измерить, справляются ли пользователи без подсказок.',[['filter','фильтр'],['measure','измерять']], [['What feature is confusing?','A filter','A login form','A payment page','Проблема в фильтре.'],['What test is proposed?','Two versions with volunteers','No testing','Only staff opinions','Предложено сравнить две версии.'],['What is the success criterion?','Finishing without help','More animations','Longer sessions','Важно, могут ли пользователи справиться сами.']]],
 ['B1','Late Hotel Arrival','Путешествия',['Guest: Our flight is delayed, so we may arrive after midnight.','Receptionist: Thank you for letting us know.','Guest: Will our reservation remain active?','Receptionist: Yes, I have noted your late arrival.','Guest: Is the front desk open all night?','Receptionist: Yes, it operates twenty-four hours.'], 'Из-за задержки рейса гость приедет после полуночи. Отель сохранил бронь и подтвердил круглосуточную работу стойки.',[['reservation','бронирование'],['front desk','стойка регистрации']], [['Why will the guests arrive late?','Flight delay','Road traffic','Lost luggage','Рейс задерживается.'],['Is the reservation still active?','Yes','No','Only until ten','Бронь сохраняется.'],['When is reception available?','All night','Until nine','Only mornings','Стойка работает круглосуточно.']]],
 ['B1','Sharing Meeting Notes','Работа',['Alex: I have drafted notes from the workshop.','Bea: Did you separate decisions from open questions?','Alex: Yes, and I added owners for each next step.','Bea: Excellent. Could you send the summary by Friday?','Alex: I can do that by Thursday afternoon.','Bea: Thanks. That gives us time to review.'], 'Алекс подготовил записи встречи, отделив решения от открытых вопросов и указав ответственных. Он обещает отправить сводку в четверг днём, раньше пятничного срока.',[['owners','ответственные'],['open questions','открытые вопросы']], [['What was added to next steps?','Owners','Prices','Passwords','К шагам добавили ответственных.'],['When is the requested deadline?','Friday','Monday','Wednesday','Попросили прислать до пятницы.'],['When can Alex send the notes?','Thursday afternoon','Saturday','Friday night','Алекс сможет прислать в четверг днём.']]],
 ['B1','Disputed Card Charge','FinTech',['Customer: This charge appears twice in my banking app.','Agent: One entry is settled; the other may be an authorization hold.','Customer: So was I charged twice?','Agent: We cannot conclude that from these entries alone.','Customer: What happens next?','Agent: We will document the case and confirm the status with the provider.'], 'Клиент видит двойную запись в приложении. Одна операция проведена, другая может быть блокировкой. Специалист документирует обращение и уточняет статус у провайдера.',[['authorization hold','авторизационная блокировка'],['settled','проведённый']], [['What may the second entry be?','An authorization hold','An approved chargeback','A completed refund','Вторая запись может быть блокировкой.'],['Does the agent confirm double charging?','No','Yes','Only if asked again','Двойное списание не подтверждено.'],['Who will verify the status?','The provider','A friend','A courier','Статус уточнят у провайдера.']]],
 ['B1','Preparing a Workshop','Учёба',['Organizer: We have thirty registrations, but only twenty seats.','Assistant: Could we use the larger room upstairs?','Organizer: It is free after two p.m.','Assistant: Then let us start at two thirty.','Organizer: Please inform everyone about the new time.','Assistant: I will send an email today.'], 'На семинар записались тридцать человек, но мест двадцать. Организаторы выбирают зал побольше наверху и переносят начало на 14:30, после чего уведомят участников.',[['registrations','регистрации'],['seats','места']], [['How many people registered?','Thirty','Twenty','Forty','Записались тридцать человек.'],['When will the workshop start?','Two thirty','One thirty','Three','Начало в 14:30.'],['How will attendees be informed?','Email','Printed letters','Phone calls only','Участникам отправят письмо.']]],
 ['B2','Discussing Incident Evidence','IT / FinTech',['Lead: The outage started shortly after deployment.','Engineer: That timing is suggestive, but it does not prove the release caused it.','Lead: What evidence do we have?','Engineer: Connection usage peaked while a legacy setting limited capacity.','Lead: What should the report recommend?','Engineer: Load testing and a verified rollback procedure.'], 'Команда выясняет причины сбоя после релиза. Время совпадения не доказывает причину; данные указывают на ограничение подключений. Предлагаются нагрузочные тесты и проверенная процедура отката.',[['legacy setting','устаревшая настройка'],['rollback','откат']], [['What evidence was found?','Connection peak and capacity limit','A fraudulent email','Missing employee ID','Найден пик нагрузки и ограничение подключений.'],['What should not be treated as proof?','Timing alone','Log data','A verified configuration','Совпадение по времени недостаточно.'],['What prevention is proposed?','Load tests and rollback','No monitoring','Deleting all logs','Предложены тесты и процедура отката.']]],
 ['B2','A Balanced Policy Review','Карьера',['Director: Some employees prefer remote work, while others value office collaboration.','Analyst: Could we compare output and feedback over a trial period?','Director: Yes, but attendance alone may not reflect performance.','Analyst: Let us define measurable outcomes first.','Director: And include accessibility needs.','Analyst: Agreed. We should publish the reasoning behind any changes.'], 'Руководитель и аналитик обсуждают политику удалённой работы. Они хотят оценить результативность и отзывы, учесть доступность и публично объяснить будущие изменения.',[['measurable outcomes','измеримые результаты'],['accessibility','доступность']], [['What should be defined first?','Measurable outcomes','A dress code','More meeting rooms','Сначала нужно определить измеримые результаты.'],['What is not sufficient alone?','Attendance','Work outcomes','Feedback','Одной посещаемости недостаточно.'],['What else should policy account for?','Accessibility needs','Coffee prices','Parking colors','Нужно учесть доступность.']]],
 ['B2','Understanding Exchange Costs','FinTech',['Client: Provider A has a lower transfer fee. Surely it is cheaper?','Advisor: Not necessarily. The exchange rate also changes the amount received.','Client: What should I compare?','Advisor: The final amount at the recipient end, along with timing and conditions.','Client: Can I treat the delivery date as guaranteed?','Advisor: Only if the provider explicitly confirms a guarantee.'], 'Клиент сравнивает международные переводы. Эксперт объясняет, что нужно учитывать не только комиссию, но и курс, итоговую сумму и условия. Срок нельзя считать гарантированным без подтверждения.',[['exchange rate','курс обмена'],['recipient','получатель']], [['What should be compared primarily?','Final recipient amount','Fee alone','Website color','Нужно сравнивать сумму получателя.'],['Why might a low fee mislead?','The rate may be worse','All fees are hidden','No money is transferred','Курс может ухудшить результат.'],['When is a delivery date guaranteed?','When expressly confirmed','Always','Never under any conditions','Гарантия должна быть явной.']]],
 ['B2','An Ethical Data Request','Технологии',['Product lead: More personal data could improve recommendations.','Privacy officer: Do we need every field for that purpose?','Product lead: Perhaps not. We could start with anonymized aggregates.','Privacy officer: That would reduce exposure while testing usefulness.','Product lead: It may delay the launch.','Privacy officer: A smaller, well-justified test is still valuable.'], 'Обсуждается запрос персональных данных для рекомендаций. Стороны выбирают сначала тест на обезличенных агрегированных данных, даже если запуск немного задержится.',[['aggregates','агрегированные данные'],['exposure','риск раскрытия']], [['What is the proposed compromise?','Anonymized aggregates','All raw personal data','No product testing','Сначала хотят использовать обезличенные агрегаты.'],['What trade-off is acknowledged?','Launch delay','No user feedback','More printed documents','Возможна задержка запуска.'],['What concern guides the decision?','Necessity of personal fields','Office size','Travel expense','Проверяют необходимость каждого поля.']]],
 ['B2','Handling a Sensitive Complaint','Customer Support',['Customer: I believe this transaction was unauthorized.','Agent: I understand the seriousness of your concern.','Customer: Can you confirm a refund right now?','Agent: The report has been recorded, but we must verify the evidence first.','Customer: What should I do in the meantime?','Agent: Please follow the security steps available in your account and our official guidance.'], 'Клиент сообщает о несанкционированной операции. Сотрудник принимает обращение, не обещает возврат до проверки и советует официальные меры безопасности.',[['unauthorized','несанкционированный'],['evidence','доказательства']], [['What does the customer suspect?','Unauthorized transaction','Shipping damage','Incorrect ticket name','Клиент подозревает несанкционированную операцию.'],['Is a refund confirmed?','No','Yes','Within an hour','Возврат не подтверждён.'],['Where is official security guidance?','Account and official instructions','Public social media chat','Another customer','Рекомендации — в аккаунте и официальных инструкциях.']]],
 ['B2','Evaluating an AI Recruitment Tool','Работа',['Recruiter: Automation might reduce the time spent screening applications.','HR specialist: How will we assess fairness?','Recruiter: We can run a supervised pilot.','HR specialist: Include human review and an appeal route.','Recruiter: We will document the criteria and results.','HR specialist: Then we can evaluate whether the benefits justify the risks.'], 'Рекрутер и HR обсуждают автоматизацию отбора резюме. Они предлагают пилот с человеческой проверкой, возможностью обжалования и прозрачными критериями.',[['pilot','пилотный проект'],['fairness','справедливость']], [['What trial is proposed?','Supervised pilot','Immediate full rollout','No evaluation','Предлагается пилот под контролем людей.'],['What safeguards are requested?','Human review and appeal','Secret criteria','No documentation','Нужны проверка человеком и апелляция.'],['What will be documented?','Criteria and results','Only office schedules','Candidate passwords','Документируют критерии и результаты.']]],
 ['B2','Explaining a Service Limitation','Payment Support',['Customer: Can you guarantee that every payout clears by Friday?','Agent: We can describe standard processing windows, but not guarantee individual outcomes.','Customer: Why not?','Agent: Some transfers require additional bank or compliance checks.','Customer: What information can you provide?','Agent: The verified status, required next steps, and updates when they become available.'], 'Клиент просит гарантировать все выплаты к пятнице. Поддержка поясняет, что срок зависит от проверок банка и соответствия требованиям и может дать только подтверждённый статус и дальнейшие шаги.',[['compliance','соответствие требованиям'],['processing window','обычный срок обработки']], [['What guarantee is refused?','All payouts by Friday','Verified status updates','Next steps','Поддержка не гарантирует все выплаты к пятнице.'],['What may affect processing?','Bank or compliance checks','A favorite color','Office snacks','Обработку могут задержать проверки.'],['What can the agent provide?','Verified status and next steps','A guaranteed date','A secret password','Можно сообщить статус и следующие шаги.']]],
 ['B2','Resolving a Research Disagreement','Образование',['Researcher: Our survey suggests that students prefer short lessons.','Colleague: The sample is small and may not represent everyone.','Researcher: Should we abandon the finding?','Colleague: No. We can report it as preliminary and collect more responses.','Researcher: Let us also compare actual completion data.','Colleague: Good. That will give us a stronger picture.'], 'Исследователи обсуждают опрос о коротких уроках. Выборка мала, поэтому вывод считают предварительным и решают собрать больше ответов и данные о завершении уроков.',[['sample','выборка'],['preliminary','предварительный']], [['What is the concern?','Small sample','Incorrect grammar','No access to internet','Выборка слишком мала.'],['How will the finding be described?','Preliminary','Final and universal','Completely false','Его назовут предварительным.'],['What other evidence will be compared?','Completion data','Office expenses','Weather reports','Сравнят реальные завершения уроков.']]],
];
function ids<T extends {level:CEFR}>(rows:T[],kind:'r'|'l'){const seen:{[k:string]:number}={};return rows.map(item=>{const index=(seen[item.level]||0)+1;seen[item.level]=index;return `${kind}-v12-${item.level.toLowerCase()}-${String(index).padStart(2,'0')}`;});}
const readingIds=ids(stories.map(([level])=>({level})),'r');
const listeningIds=ids(dialogues.map(([level])=>({level})),'l');
export const extraReading:ReadingUnit[]=stories.map(([level,title,topic,passage,translation,glossary,facts],index)=>({id:readingIds[index],level,title,topic,passage,translation,glossary,questions:quiz(facts)}));
export const extraListening:ListeningUnit[]=dialogues.map(([level,title,topic,lines,translation,keyPhrases,facts],index)=>({id:listeningIds[index],level,title,topic,lines,translation,keyPhrases,questions:quiz(facts)}));

type WritingRow=[CEFR,string,string,string,number,[string,string,string],string[],string,string,string];
const newWriting:WritingRow[]=[
 ['A1','Сообщение новому соседу','Знакомство','Поздоровайся с новым соседом, представься, скажи, в какой квартире живёшь, и предложи помощь.',25,['Я представился','Я указал квартиру','Я предложил помощь'],['My name is…','I live in apartment…','Can I help you?'], 'Hi! My name is Kate. I live in apartment five. Welcome to our building! I work from home and I like this neighborhood. If you need help with the laundry room or the bus stop, please ask me. Have a nice day!', 'Привет! Меня зовут Кейт, я живу в квартире пять. Добро пожаловать! Если понадобится помощь с прачечной или остановкой, обращайся.', 'В дружелюбном сообщении достаточно коротких предложений в Present Simple.'],
 ['A1','Мои любимые выходные','Свободное время','Расскажи, что делаешь утром, днём и вечером в выходной. Упомяни хотя бы одно место.',30,['Есть утреннее действие','Есть дневное действие и место','Есть вечернее действие'],['On Saturday morning…','In the afternoon…','In the evening…'], 'On Saturday morning, I usually make breakfast at home. Then I walk to the park with a friend. In the afternoon, we drink coffee at a small café. In the evening, I read a book or watch a movie. I like quiet weekends because I can relax.', 'В субботу утром я завтракаю дома, затем гуляю в парке с другом. Днём мы пьём кофе. Вечером читаю или смотрю фильм.', 'Используй usually для привычек и разные выражения времени.'],
 ['A1','Простой заказ в кафе','Еда','Напиши короткий диалог покупателя и бариста: заказ, выбор напитка и вопрос о цене.',30,['Я попросил напиток','Я уточнил размер или температуру','Я спросил цену и поблагодарил'],['I would like…','Small, please.','How much is it?'], 'Customer: Hello! I would like a small coffee, please. Barista: Sure. Hot or iced? Customer: Hot, please. Do you have milk? Barista: Yes, we do. Customer: Great. How much is it? Barista: Four dollars. Customer: Thank you. Have a nice day!', 'Клиент заказывает небольшой горячий кофе с молоком, спрашивает цену и благодарит.', 'Would like — вежливее, чем I want.'],
 ['A1','Письмо учителю','Учёба','Напиши учителю, что пропустишь урок завтра, кратко объясни причину и спроси, что повторить дома.',30,['Я указал дату пропуска','Я назвал причину','Я попросил домашнее задание'],['I cannot come to class…','Because…','What should I study?'], 'Hello, Mr. Green. I cannot come to English class tomorrow because I have a doctor appointment. I am sorry about that. Could you please tell me what we will study? I want to practice at home and be ready for the next lesson. Thank you!', 'Я не смогу прийти на английский завтра из-за врача. Подскажите, что вы будете изучать, чтобы я подготовился дома.', 'Для просьбы используй Could you please…?'],
 ['A1','Мой город','Город','Опиши свой город: два места, транспорт, одно любимое место и почему оно тебе нравится.',35,['Я назвал город','Я описал два места и транспорт','Я объяснил любимое место'],['There is a…','You can go by…','My favorite place is…'], 'I live in a large city. There are many parks, shops, and museums here. I usually take the bus to work, but I walk in the evening. My favorite place is a small park near my home. It has old trees and comfortable benches. I like it because it is quiet.', 'Я живу в большом городе с парками и музеями. Езжу на работу автобусом, а любимое место — тихий парк у дома.', 'There is — для одного объекта, there are — для нескольких.'],
 ['A1','Сообщение о потерянной вещи','Повседневная жизнь','Напиши сообщение другу: что потерял, где видел вещь в последний раз и попроси помочь найти её.',30,['Я назвал предмет','Я указал последнее место','Я вежливо попросил помощи'],['I cannot find…','I saw it at…','Could you help me?'], 'Hi, Ben. I cannot find my blue backpack. I saw it in the classroom yesterday after lunch. There is a small notebook inside. Could you please check the classroom when you have time? Please send me a message if you see it. Thank you very much!', 'Привет, Бен. Не могу найти синий рюкзак. Вчера после обеда он был в классе. Посмотри, пожалуйста, не остался ли он там.', 'С last time и yesterday часто используется Past Simple.'],
 ['A2','Перенос записи','Здоровье','Напиши в клинику с просьбой перенести приём. Укажи старое и новое время и попроси подтверждение.',45,['Я указал текущую запись','Я предложил новое время','Я попросил подтверждение'],['I have an appointment on…','Could I reschedule…?','Please confirm…'], 'Hello, I have an appointment on Tuesday at ten in the morning, but I cannot attend because of a work meeting. Could I please reschedule it for Friday afternoon, if a slot is available? I can also come on Thursday after four. Please let me know which time works and send me a confirmation. Thank you for your help.', 'Здравствуйте. У меня запись на вторник в десять, но из-за рабочей встречи я не смогу прийти. Могу ли я перенести визит на пятницу после обеда или четверг после четырёх? Подтвердите, пожалуйста, новое время.', 'Сочетай Present Simple для текущих условий и could для вежливой просьбы.'],
 ['A2','Отзыв о покупке','Покупки','Напиши отзыв на товар: что заказал, как прошло получение, что понравилось и что можно улучшить.',50,['Я указал товар','Я описал опыт получения','Я указал плюс и минус'],['I ordered…','The delivery was…','It would be better if…'], 'I ordered a pair of headphones last week. The package arrived two days later, and everything was packed carefully. The sound is clear, and the headphones are comfortable. However, the cable is shorter than I expected. It would be better if the store included a longer cable. Overall, I am happy with my purchase and would recommend it to someone who listens to music at home.', 'На прошлой неделе я заказал наушники. Их доставили через два дня и хорошо упаковали. Звук чистый, но кабель коротковат. В целом покупкой доволен.', 'Для описания законченной покупки используй Past Simple.'],
 ['A2','Рассказ о поездке на поезде','Путешествия','Опиши неожиданную задержку поезда, что ты сделал и чем закончилась ситуация.',50,['Я описал причину задержки','Я рассказал о своих действиях','Я объяснил результат'],['The train was delayed…','I decided to…','In the end…'], 'Last month I traveled to another city by train. My train was delayed because of heavy rain, so I checked the station app for updates. I sent a message to my friend and told her I would arrive later than planned. We moved our lunch reservation to the afternoon. In the end, I arrived safely and still had time to visit the city center.', 'В прошлом месяце поезд задержался из-за дождя. Я проверил приложение и предупредил подругу. Мы перенесли обед, и я всё равно успел погулять по центру.', 'Связывай события словами so, because, in the end.'],
 ['A2','Запрос по статусу заказа','Customer Support','Напиши покупателю ответ о посылке, которая ещё в пути. Запроси номер заказа и не гарантируй дату.',50,['Я проявил понимание','Я запросил номер заказа','Я не дал неподтверждённых обещаний'],['I understand your concern.','Could you provide the order number?','I will check the latest status.'], 'Hello, thank you for contacting us. I understand that you are waiting for your order, and I am sorry for the inconvenience. Could you please provide the order number so I can check its latest tracking status? I will review the information available and explain the next steps. I cannot confirm an exact delivery date before the carrier updates the tracking record. Thank you for your patience.', 'Спасибо за обращение. Я понимаю, что вы ждёте посылку. Уточните номер заказа: я проверю отслеживание и сообщу дальнейшие шаги. Точную дату до обновления перевозчика подтвердить не могу.', 'В поддержке избегай guarantee без подтверждённых данных.'],
 ['A2','Письмо о совместной квартире','Жильё','Напиши будущему соседу: обсуди аренду, уборку, гостей и предложи обсудить детали.',50,['Я обсудил оплату','Я предложил порядок уборки','Я упомянул гостей и дальнейшее обсуждение'],['We could split…','How about a cleaning schedule?','Let me know what you think.'], 'Hi, Alex. I am excited that we may share an apartment next month. I think we could split the rent equally and pay our own phone bills. How about creating a simple cleaning schedule? That would help us keep the kitchen and bathroom tidy. I would also like us to ask each other before inviting overnight guests. Let me know what you think, and we can talk about the details this weekend.', 'Привет, Алекс. Предлагаю делить аренду поровну и составить график уборки. Было бы хорошо согласовывать гостей, остающихся на ночь. Давай обсудим на выходных.', 'How about + ing подходит для предложения идеи.'],
 ['A2','Записка о новой привычке','Здоровье','Расскажи, какую полезную привычку решил развить, как продвигался и что планируешь дальше.',50,['Я назвал новую привычку','Я рассказал о первых результатах','Я сформулировал будущий план'],['I decided to…','I have started…','Next month I am going to…'], 'I decided to walk more often because I was spending too much time at my desk. Two weeks ago, I started taking short walks after lunch. I have already noticed that I feel more energetic in the afternoon. It has not been easy every day, especially when the weather is bad. Next month I am going to invite a friend to join me twice a week.', 'Я решил чаще гулять после обеда. За две недели заметил больше энергии, хотя иногда мешает погода. В следующем месяце хочу приглашать друга на прогулки.', 'Present Perfect подойдёт для результата, важного сейчас.'],
 ['B1','Передача сложного тикета','Payment Support','Напиши передачу смены по спорному платежу: факты, выполненные проверки, неизвестные данные и следующий шаг.',70,['Я отделил подтверждённое от неизвестного','Я перечислил проверки','Я указал конкретный следующий шаг'],['Confirmed so far…','We have checked…','The next shift should…'], 'Handover for ticket 842: The customer reported a card payment that appears twice in the transaction history. We verified that the first entry is settled, but the second entry is still being reviewed by the provider. We have checked the reference numbers and attached the available logs in the approved system. We have not confirmed whether the second entry represents an authorization hold. The next shift should review the provider response, update the customer with confirmed information and avoid promising a refund before verification.', 'Передача тикета 842: клиент видит два платежа. Первая запись проведена, вторая проверяется провайдером. Идентификаторы и журналы собраны. Следующая смена должна получить подтверждённый статус и сообщить клиенту без преждевременного обещания возврата.', 'Сохраняй различие между confirmed и not yet verified.'],
 ['B1','Собеседование о сильных сторонах','Карьера','Ответь рекрутеру на вопрос о своих сильных сторонах, приведи рабочий пример и объясни пользу для команды.',70,['Я назвал конкретный навык','Я привёл пример','Я объяснил ценность для команды'],['One of my strengths is…','For example…','This helps me…'], 'One of my strengths is clear written communication. In my previous customer service role, I learned to summarize complicated situations in simple language. For example, when a customer was confused about the status of an order, I checked the details before explaining what we knew and what still needed confirmation. This helped reduce misunderstandings and made it easier for colleagues to continue working on the case. I believe this skill is valuable in remote support, where clear messages and careful documentation are essential.', 'Моя сильная сторона — ясная письменная коммуникация. На прежней работе я научился объяснять сложные ситуации простыми словами и документировать действия для коллег.', 'Пример должен быть правдивым; не выдумывай опыт для реального собеседования.'],
 ['B1','Письмо арендодателю','Жильё','Сообщи арендодателю о протечке, приложенных фотографиях и попроси организовать осмотр без обвинений.',70,['Я описал проблему конкретно','Я предложил доказательства','Я вежливо запросил следующий шаг'],['I noticed…','I have attached photos.','Could we arrange an inspection?'], 'Hello, I am writing about a leak near the living room window in apartment 12. I first noticed it during heavy rain on Monday, and the wall was still damp the following morning. I have attached dated photos to show the affected area. Could we please arrange an inspection and discuss the next steps for repair? I understand that the cause may need professional assessment, so I am not making assumptions about it. Please let me know when a technician could visit. Thank you for your assistance.', 'Пишу о протечке у окна в квартире 12. Я обнаружил её во время дождя и приложил фотографии. Прошу организовать осмотр и обсудить ремонт без предположений о причине.', 'Используй нейтральные фактические формулировки.'],
 ['B1','Отчёт о командной встрече','Работа','Напиши итог встречи: принятое решение, открытые вопросы, ответственные и сроки.',75,['Есть принятое решение','Есть открытые вопросы','Есть ответственные и сроки'],['We agreed to…','The following questions remain open…','The owner of this action is…'], 'Meeting summary: The team agreed to update the support handover template so that confirmed facts and pending checks appear in separate sections. We also decided to add a clear owner and deadline to every unresolved ticket. The main open question is whether the current system can show provider responses automatically. Maya will investigate this by Thursday, while Ben will prepare a revised template by Friday. We will review both items at the next weekly meeting and ask for feedback from agents who work night shifts.', 'Итог встречи: команда обновит шаблон передачи смены, разделит факты и ожидающие проверки и назначит ответственных. Майя исследует техническую возможность к четвергу, Бен подготовит шаблон к пятнице.', 'Выделяй решения, открытые вопросы и действия в отдельных смысловых частях.'],
 ['B1','Объяснение жалобы покупателю','Customer Support','Ответь на недовольное сообщение клиента об ошибочной доставке: извинись, уточни детали и объясни процесс.',70,['Есть уважительное извинение','Есть запрос необходимых данных','Есть реалистичные шаги без гарантий'],['I am sorry for the inconvenience.','Could you share…?','We will review the available information.'], 'Thank you for bringing this issue to our attention. I am sorry that you received a different item from the one you ordered. I understand how frustrating that can be. Could you please share your order number and, if possible, a photo of the item received? We will compare the information with the order record and explain the exchange or return options available under the store policy. I cannot promise a particular outcome before reviewing the details, but I will make sure you know the next steps.', 'Спасибо, что сообщили об ошибке. Сожалею, что вам пришёл другой товар. Пришлите номер заказа и фотографию; мы сверим данные и объясним доступные варианты обмена или возврата.', 'Вежливость и чёткие шаги важнее пустых обещаний.'],
 ['B1','Мнение об удалённой работе','Эссе','Напиши короткий текст о плюсах и минусах удалённой работы и сделай вывод.',80,['Я представил преимущество','Я представил недостаток','Я сделал взвешенный вывод'],['One advantage is…','On the other hand…','In my opinion…'], 'Remote work gives employees more flexibility and can save the time they would otherwise spend commuting. This can be particularly helpful for tasks that require concentration, such as responding to customer messages or preparing reports. On the other hand, communication can become slower when colleagues work in different time zones, and new employees may have fewer chances to learn informally. In my opinion, a successful remote team needs clear expectations, useful documentation and regular opportunities to ask questions. The location is important, but the quality of teamwork matters more.', 'Удалённая работа экономит время и помогает сосредоточиться, но иногда усложняет общение. На мой взгляд, для успеха нужны ясные ожидания и хорошая документация.', 'Используй связки on the other hand, however, in my opinion.'],
 ['B2','Анализ инцидента платежной системы','FinTech','Напиши краткий технический отчёт: наблюдения, возможная причина, ограничения выводов, действия и профилактика.',110,['Факты отделены от гипотез','Описаны действия и влияние','Предложены конкретные профилактические меры'],['The evidence currently suggests…','This has not yet been confirmed.','To reduce recurrence…'], 'Incident summary: Between 09:20 and 09:34, some customers experienced delays when submitting payments. Monitoring showed a sharp increase in connection usage during that period. The service recovered after the team rolled back a configuration change; however, the timing alone does not establish the root cause. Engineers are comparing deployment records with server logs and reviewing whether any transactions were duplicated. No final conclusions have been communicated to customers. The immediate actions are to complete the reconciliation, identify affected tickets and provide updates based on verified facts. To reduce recurrence, we propose additional load testing, clearer alert thresholds and a documented rollback drill. The report will be revised once the investigation is complete.', 'Сводка сбоя: часть платежей задерживалась с 09:20 до 09:34; мониторинг показал высокую нагрузку. Восстановление после отката не доказывает причину. Команда изучает журналы, сверяет операции и планирует тесты и улучшение оповещений.', 'B2 требует чёткого различения evidence, assumptions, and recommendations.'],
 ['B2','Спор о персональных данных','Эссе','Напиши аргументированное мнение о том, должна ли компания собирать больше пользовательских данных ради персонализации.',110,['Я раскрыл преимущества','Я рассмотрел риски и контраргумент','Я предложил сбалансированный подход'],['On the one hand…','A significant concern is…','A proportionate approach would…'], 'Personalized services can help users find relevant information more quickly, but gathering additional data is not automatically justified. On the one hand, better recommendations may reduce frustration and improve a product. On the other, collecting unnecessary details increases exposure if information is misused or leaked. Transparency alone is insufficient when users lack meaningful choice. In my view, companies should begin with the smallest dataset needed to test a specific benefit, explain their purposes in accessible language and allow appropriate controls. Independent review and careful retention limits can strengthen accountability. Personalization should be evaluated against both measurable value and the privacy cost imposed on people who use the service. This balance matters in practice.', 'Персонализация полезна, но не оправдывает любой сбор данных. Компании стоит начинать с минимального набора, объяснять цели и контролировать срок хранения.', 'Контраргумент и обоснованный компромисс — ключевые элементы B2.'],
 ['B2','Внутреннее письмо о рисках','Payment Support','Объясни руководителю риск необоснованных обещаний сроков выплат и предложи улучшения шаблонов поддержки.',110,['Я объяснил конкретный риск','Я предложил практические улучшения','Я описал способ оценить результат'],['A recurring concern is…','I recommend that we…','We could measure improvement by…'], 'Subject: Improving payment status communication. A recurring concern in our support responses is the use of completion times that have not been verified by the payment provider. Although such estimates may appear reassuring, they can create unrealistic expectations and additional complaints when delays occur. I recommend revising our response templates to distinguish confirmed status from an estimated processing window. Agents should request only the information required for investigation, document uncertain points and communicate the next review step clearly. We could evaluate the change by monitoring repeat contacts, escalations related to promised deadlines and customer feedback over a four-week trial. These measures would help us improve clarity without making commitments the team cannot control.', 'В письме руководителю объясняется риск обещаний неподтверждённых сроков, предлагаются новые шаблоны ответов и четырёхнедельная оценка по повторным обращениям и эскалациям.', 'Не подменяй план измерений вымышленной статистикой.'],
 ['B2','Структурированное мнение об ИИ в найме','Карьера','Обсуди, когда ИИ уместен при отборе кандидатов, а когда необходимо участие человека.',110,['Я описал полезное применение','Я раскрыл риски и ограничения','Я предложил контроль и ответственность'],['Automated tools can assist…','However, it would be misleading to…','Ultimately, accountability must…'], 'Automated tools can help recruitment teams organize applications and identify missing administrative information, particularly when the volume of candidates is high. Nevertheless, it would be misleading to assume that an algorithm produces fair decisions simply because it applies the same rules consistently. Training data may reflect historical inequalities, and unexplained rankings can make appeals difficult. In my view, employers should limit automation to clearly defined purposes, evaluate outcomes across relevant groups and provide meaningful human review. Candidates should know how significant decisions are made and how they can challenge errors. Ultimately, accountability must remain with trained professionals rather than being transferred to software that cannot explain its judgments. Meaningful oversight remains essential.', 'Автоматизация помогает систематизировать резюме, но риск исторической предвзятости и непрозрачности требует оценки, апелляций и решений с участием человека.', 'Строй текст вокруг тезиса, возражения и аргументированного вывода.'],
 ['B2','Сложный ответ о спорной операции','Customer Support','Напиши клиенту о спорной операции: подтвердить получение обращения, обозначить факты, процедуру и границы обещаний.',110,['Я подтвердил обращение и проявил эмпатию','Я различил известные и неизвестные сведения','Я описал проверку и безопасные действия'],['Based on the information available…','We are not yet in a position to confirm…','Once verification is complete…'], 'Thank you for reporting the transaction. I understand that an unexpected charge may cause considerable concern, and I appreciate the opportunity to investigate. Based on the information currently available, your report has been registered and the transaction reference has been identified. We are not yet in a position to confirm whether the entry is a completed charge or a temporary authorization. Our team is reviewing the relevant records with the payment provider, and we will explain the available next steps once the status has been verified. Please do not send passwords, security codes or full card details through this chat. If you suspect unauthorized access, follow the security instructions in your account or official support channels. Thank you for your patience.', 'Спасибо за обращение. Мы получили сообщение и нашли идентификатор. Пока неясно, окончательное это списание или временная блокировка. Мы проверяем записи с провайдером, не запрашивая пароли и коды.', 'Фразы not yet in a position to confirm и based on available information предотвращают ложные гарантии.'],
 ['B2','Политика гибридной работы','Эссе','Напиши позиционный документ о пробной гибридной работе: критерии успеха, риски и рекомендации.',110,['Я назвал измеримые критерии','Я рассмотрел обе стороны','Я дал выполнимую рекомендацию'],['A trial period would allow…','One potential drawback is…','I therefore recommend…'], 'A hybrid work policy should be judged by its effect on results and employee wellbeing, not simply by how often people enter the office. A limited trial could offer useful evidence if teams agree on measurable goals, shared availability hours and clear expectations for collaboration. Some employees may gain focus and flexibility, while others could find mentoring and informal communication more difficult. These differences should be examined rather than dismissed. I therefore recommend a three-month pilot with regular feedback, attention to accessibility needs and a transparent review of task outcomes. Management should publish the criteria in advance and explain any revisions after the trial. This approach is more credible than announcing a universal solution before gathering evidence.', 'Гибридный формат следует оценивать по результатам и благополучию сотрудников. Предлагается трёхмесячный пилот, понятные критерии, обратная связь и учёт доступности.', 'Убедительный текст требует измеримых критериев вместо общих лозунгов.'],
];
const writeIds=ids(newWriting.map(([level])=>({level})),'r').map(id=>id.replace('r-v12-','w-v12-'));
